import importlib.util,json
from pathlib import Path
p=Path(__file__).with_name('run_worker.py');spec=importlib.util.spec_from_file_location('replacement_worker',p);w=importlib.util.module_from_spec(spec);spec.loader.exec_module(w)
existing=json.loads((w.R.parent/'cross-plan-input.json').read_text());compact=[{k:v for k,v in x.items() if k in ['group','scenario','premise','mechanism','memory_focus']} for x in existing]
prompt='''Use no tools. Plan exactly40 genuinely distinct natural English conversations, groups c_replace_001 through c_replace_040. These are replacements for a quality-first1000conversation training-candidate corpus. Existing1000 plans are below: avoid their concrete tasks, constraints and inference patterns, not merely rename entities. Favor direct grounded answers and everyday discussion, not advice/coaching. Families exactly15 grounding,10 language_explanation,10 ordinary,5 correction. No memory family; no tools/maths/science factual specialization. Corrections must come from user changing their own supplied facts/intention, never intentionally wrong assistant then apology. Each plan must sustain4–8 short useful exchanges without filler or artificial quiz. Grounding should use small user-supplied invented passages/notices/dialogue excerpts and examine what is/isn't entailed, preserve subtle English scope; not new empty generic notices. English explanation should avoid existing basic active/passive, modal uncertainty, common homonyms; use useful but basic register/pragmatics, referents and phrasing with concrete examples. Ordinary discussion should include normal curiosity, grounded comparisons and reactions, not all suggestions. Avoid identical 'You could' reply starts. No specialist factual assertions requiring external verification. No external actions. Output schemaJSON only; each scenario has premise and materially distinctive mechanism and diversity_key.\nEXISTING PLANS:\n'''+json.dumps(compact,ensure_ascii=False)
d,path=w.cli('plan',prompt,w.R/'plan-schema.json');assert len(d['scenarios'])==40
print('40replacement plans created',flush=True)
